/**
 * HbbTV Emulator - HLS Player
 * Wraps hls.js for HLS playback.
 */



function createHlsPlayer(videoElement, url) {
  var hls = null;

  if (Hls.isSupported()) {
    hls = new Hls({
      enableWorker: true,
      lowLatencyMode: false,
      maxBufferLength: 30,
      maxMaxBufferLength: 60
    });

    hls.loadSource(url);
    hls.attachMedia(videoElement);

    hls.on(Hls.Events.MANIFEST_PARSED, function () {
      console.log('[HbbTV Emulator] HLS manifest parsed, starting playback');
      videoElement.play().catch(function (e) {
        console.warn('[HbbTV Emulator] HLS autoplay blocked:', e.message);
      });
    });

    hls.on(Hls.Events.ERROR, function (event, data) {
      if (data.fatal) {
        console.error('[HbbTV Emulator] HLS fatal error:', data.type, data.details);
        switch (data.type) {
          case Hls.ErrorTypes.NETWORK_ERROR:
            hls.startLoad();
            break;
          case Hls.ErrorTypes.MEDIA_ERROR:
            hls.recoverMediaError();
            break;
          default:
            hls.destroy();
            break;
        }
      }
    });

    console.log('[HbbTV Emulator] HLS player initialized for:', url);
  } else if (videoElement.canPlayType('application/vnd.apple.mpegurl')) {
    // Native HLS support (Safari)
    videoElement.src = url;
    videoElement.play().catch(function () {});
    console.log('[HbbTV Emulator] Using native HLS for:', url);
  }

  return {
    destroy: function () {
      if (hls) {
        try {
          hls.destroy();
        } catch (e) {
          console.warn('[HbbTV Emulator] HLS player destroy error:', e);
        }
        hls = null;
      }
    },

    getPlayer: function () {
      return hls;
    }
  };
}

;// ./src/players/native-player.js
/**
 * HbbTV Emulator - Native Player
 * Handles MP4/WebM playback via native HTML5 video.
 */

function createNativePlayer(videoElement, url) {
  videoElement.src = url;

  var playPromise = videoElement.play();
  if (playPromise && playPromise.catch) {
    playPromise.catch(function (e) {
      console.warn('[HbbTV Emulator] Native player autoplay blocked:', e.message);
    });
  }

  console.log('[HbbTV Emulator] Native player initialized for:', url);

  return {
    destroy: function () {
      videoElement.pause();
      videoElement.removeAttribute('src');
      videoElement.load();
    },

    getPlayer: function () {
      return videoElement;
    }
  };
}

;// ./src/players/player-type.js
/**
 * HbbTV Emulator - Player Type Detection
 * Decides which player (dash/hls/native) should handle a URL.
 */

function detectPlayerType(url) {
  if (!url) return 'native';

  // Decide by the file extension of the URL path (query/fragment stripped)
  var path = url.toLowerCase().split('#')[0].split('?')[0];
  var extMatch = path.match(/\.([a-z0-9]+)$/);
  if (extMatch) {
    var ext = extMatch[1];
    if (ext === 'mpd') return 'dash';
    if (ext === 'm3u8') return 'hls';
    if (ext === 'mp4' || ext === 'm4v' || ext === 'webm' || ext === 'mpeg' ||
        ext === 'mpg' || ext === 'ts' || ext === 'mp3' || ext === 'aac') {
      return 'native';
    }
  }

  // No recognizable extension: fall back to heuristics
  if (path.indexOf('.mpd') !== -1 || path.indexOf('dash') !== -1) {
    return 'dash';
  }
  if (path.indexOf('.m3u8') !== -1) {
    return 'hls';
  }
  return 'native';
}

